const libFableServiceProviderBase = require('fable-serviceproviderbase');

const libGraphGeometry = require('./GraphGeometry-Core.js');

/**
 * PictProvider-GraphGeometry
 *
 * Thin Fable service wrapper around the dependency-free GraphGeometry core, so
 * apps that already speak the service-provider pattern can register it and reach
 * the same math through dependency injection. All methods delegate to the core;
 * there is no behavior here beyond delegation.
 *
 * Most consumers should require the core directly:
 *   const GraphGeometry = require('pict-provider-graphgeometry').GraphGeometry;
 */
const _ProviderConfiguration =
{
	ProviderIdentifier: 'PictProviderGraphGeometry'
};

class PictProviderGraphGeometry extends libFableServiceProviderBase
{
	constructor(pFable, pOptions, pServiceHash)
	{
		let tmpOptions = Object.assign({}, _ProviderConfiguration, pOptions);
		super(pFable, tmpOptions, pServiceHash);

		this.serviceType = 'PictProviderGraphGeometry';

		this.geometry = new libGraphGeometry(this.options);
	}

	getEdgeFromSide(pSide)
	{
		return this.geometry.getEdgeFromSide(pSide);
	}

	sideDirection(pSide)
	{
		return this.geometry.sideDirection(pSide);
	}

	getEdgeCenter(pRectData, pSide)
	{
		return this.geometry.getEdgeCenter(pRectData, pSide);
	}

	getPortLocalPosition(pSide, pIndex, pTotal, pWidth, pHeight, pTitleBarHeight, pPortCountsBySide)
	{
		return this.geometry.getPortLocalPosition(pSide, pIndex, pTotal, pWidth, pHeight, pTitleBarHeight, pPortCountsBySide);
	}

	buildPortCountsBySide(pPorts)
	{
		return this.geometry.buildPortCountsBySide(pPorts);
	}

	computeMinimumNodeHeight(pPorts, pTitleBarHeight)
	{
		return this.geometry.computeMinimumNodeHeight(pPorts, pTitleBarHeight);
	}

	// Internal zone helpers are exposed for parity with the legacy provider so
	// existing callers and tests that reach them keep working.
	_getZoneFromSide(pSide)
	{
		return this.geometry._getZoneFromSide(pSide);
	}

	_getZoneKeysForEdge(pEdge)
	{
		return this.geometry._getZoneKeysForEdge(pEdge);
	}

	_computeAdaptiveZone(pSide, pPortCountsBySide)
	{
		return this.geometry._computeAdaptiveZone(pSide, pPortCountsBySide);
	}
}

module.exports = PictProviderGraphGeometry;

module.exports.default_configuration = _ProviderConfiguration;

// The dependency-free core, for direct use and unit testing.
module.exports.GraphGeometry = libGraphGeometry;
